package com.ecopulse.config; import com.ecopulse.model.*; import com.ecopulse.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import java.math.BigDecimal; import java.time.*; import java.util.*; @Configuration public class SeedConfig { @Bean CommandLineRunner seed(UserRepository users,BuildingRepository buildings,ConsumptionRepository records){return args->{ if(records.count()>0)return; var bs=buildings.findByOrganizationId(1L); Random r=new Random(42); for(int d=120;d>=0;d--){for(var b:bs){double factor=1+(b.occupancy/1000.0); double base=(b.name.contains("Engineering")?1250:b.name.contains("Library")?850:b.name.contains("Hostel")?1050:500)*factor; double weekday=LocalDate.now().minusDays(d).getDayOfWeek().getValue()>=6?.68:1.0; double spike=(d==18&&b.name.contains("Engineering"))?1.65:1.0; ConsumptionRecord x=new ConsumptionRecord(); x.organizationId=1L;x.buildingId=b.id;x.recordedAt=LocalDate.now().minusDays(d).atStartOfDay(ZoneOffset.UTC).toInstant();x.electricityKwh=BigDecimal.valueOf(base*weekday*spike*(.92+r.nextDouble()*.16));x.waterLiters=BigDecimal.valueOf(b.occupancy*weekday*(8+r.nextDouble()*4));x.wasteKg=BigDecimal.valueOf(b.occupancy*weekday*(.07+r.nextDouble()*.04));x.costInr=x.electricityKwh.multiply(BigDecimal.valueOf(8.5));x.co2Kg=x.electricityKwh.multiply(BigDecimal.valueOf(.7));x.source="DEMO";x.importKey="demo-"+b.id+"-"+d;records.save(x);}}};} }
